/* Keep native speech alive, distinguish intentional cancellation, and expose voice diagnostics. */
const audioEngine=window.speechSynthesis||null;
let audioJob=0,audioUtterances=[],audioStartTimer=null,audioQueueTimer=null,audioText='',audioStatus='尚未试听',audioError='',audioVoiceURI='',audioSecondVoiceURI='';
try{const saved=JSON.parse(localStorage.getItem('hajime-audio-v1')||'{}');audioVoiceURI=saved.voiceURI||'';audioSecondVoiceURI=saved.secondVoiceURI||'';}catch{}
function japaneseVoices(){try{return (audioEngine?.getVoices()||[]).filter(v=>/^ja(?:$|-|_)/i.test(v.lang));}catch{return [];}}
function selectedJapaneseVoice(){const voices=japaneseVoices();return voices.find(v=>v.voiceURI===audioVoiceURI)||voices.find(v=>v.localService)||voices.find(v=>v.default)||voices[0];}
function secondJapaneseVoice(){const first=selectedJapaneseVoice(),voices=japaneseVoices();return voices.find(v=>v.voiceURI===audioSecondVoiceURI)||voices.find(v=>v.voiceURI!==first?.voiceURI&&v.localService)||voices.find(v=>v.voiceURI!==first?.voiceURI)||first;}
function dialogueTurns(text){
 const input=String(text).trim();
 const pattern=/(?:^|(?<=[。！？!?\n]))[ \t\r\n]*([\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}A-Za-z0-9・]{1,12})[：:]\s*/gu;
 const matches=[...input.matchAll(pattern)];
 if(!matches.length||/^\d+$/.test(matches[0][1])||input.slice(0,matches[0].index).trim())return [{speaker:'',text:input}];
 return matches.map((m,i)=>({speaker:m[1],text:input.slice(m.index+m[0].length,matches[i+1]?.index??input.length).trim()})).filter(t=>t.text);
}
function audioState(message,error=''){audioStatus=message;audioError=error;const el=$('#audioStatus');if(el)el.textContent=message;const detail=$('#audioError');if(detail)detail.textContent=error?`诊断代码：${error}`:'';}
function speechParts(text){return String(text).trim().split(/(?<=[。！？!?])|\n+/u).flatMap(s=>{s=s.trim();const out=[];while(s.length>120){let cut=s.lastIndexOf('、',120);if(cut<30)cut=120;else cut++;out.push(s.slice(0,cut));s=s.slice(cut);}if(s)out.push(s);return out;});}
stopAudio=function(){audioJob++;clearTimeout(audioStartTimer);clearTimeout(audioQueueTimer);audioStartTimer=null;audioQueueTimer=null;for(const u of audioUtterances){u.onerror=null;u.onend=null;u.onstart=null;}const active=audioUtterances.length||audioEngine?.speaking||audioEngine?.pending;audioUtterances=[];audioText='';if(audioEngine&&active){try{audioEngine.cancel();}catch{}}if(active)audioState('播放已停止');};
function audioFailure(code){const descriptions={network:'在线声音连接失败。请在语音设置里改选本地声音，或换浏览器试听。','audio-busy':'音频设备正忙，请稍后重试。','audio-hardware':'无法使用音频输出，请检查扬声器或耳机。','not-allowed':'浏览器拒绝了语音播放。请直接点击试听；仍失败时可在 Edge 或 Chrome 打开本站。','language-unavailable':'当前声音不能播放日语。请换一个日语声音。','voice-unavailable':'所选声音不可用。请在语音设置里重新选择。','synthesis-unavailable':'浏览器没有可用的合成语音引擎。请换浏览器或安装系统日语语音。','synthesis-failed':'所选声音合成失败，请换一个日语声音或浏览器试听。','start-timeout':'声音未能启动，请换一个日语声音或浏览器试听。'};stopAudio();audioState(descriptions[code]||'语音播放失败，请打开语音设置查看声音并试听。',code||'unknown');toast(audioStatus);}
speak=function(text,rate=.85){const normalized=String(text??'').trim();if(!normalized)return;if(!audioEngine){audioState('当前浏览器不支持语音播放。可在 Edge 或 Chrome 打开本站。','unsupported');toast(audioStatus);return;}if(audioText===normalized&&audioUtterances.length)return;const voice=selectedJapaneseVoice();if(!voice){audioState('未检测到日语声音。打开「语音设置」重新检测，或在有日语声音的浏览器中试听。','no-japanese-voice');toast(audioStatus);return;}
 stopAudio();const job=audioJob;audioText=normalized;audioState(`准备播放 · ${voice.name}`);const turns=dialogueTurns(normalized),roles=[...new Set(turns.map(t=>t.speaker).filter(Boolean))],second=secondJapaneseVoice();const parts=turns.flatMap(t=>speechParts(t.text).map(text=>({text,speaker:t.speaker,role:Math.max(0,roles.indexOf(t.speaker))})));let started=false;audioUtterances=parts.map((part,i)=>{const u=new SpeechSynthesisUtterance(part.text);u.lang='ja-JP';u.voice=part.role%2?second:voice;u.pitch=roles.length>1&&voice.voiceURI===second?.voiceURI?(part.role%2?1.18:.82):1;u.rate=Math.min(1.5,Math.max(.5,Number(rate)||.85));u.onstart=()=>{if(job!==audioJob)return;started=true;clearTimeout(audioStartTimer);audioState(`正在播放${part.speaker?' · '+part.speaker:''} · ${u.voice.name}${roles.length>1&&voice.voiceURI===second?.voiceURI?'（单声音，音高区分角色）':''}`);};u.onend=()=>{if(job!==audioJob)return;if(i===parts.length-1){audioUtterances=[];audioText='';clearTimeout(audioStartTimer);audioState(`播放完成 · ${voice.name}`);}};u.onerror=e=>{if(job!==audioJob)return;if(e.error==='canceled'||e.error==='interrupted'){stopAudio();audioState('播放已停止，可重新点击播放');return;}audioFailure(e.error);};return u;});
 // Let an earlier cancel finish before queuing the next utterance.
 audioQueueTimer=setTimeout(()=>{if(job!==audioJob)return;try{if(audioEngine.paused)audioEngine.resume();for(const u of [...audioUtterances]){if(job!==audioJob)break;audioEngine.speak(u);}if(!started&&audioUtterances.length)audioStartTimer=setTimeout(()=>{if(job===audioJob&&!started)audioFailure('start-timeout');},10000);}catch{audioFailure('synthesis-failed');}},60);
};
function renderAudioSettings(){const voices=japaneseVoices(),voice=selectedJapaneseVoice();$('#audioBody').innerHTML=`<span class="label">日语发音与听力</span><h2>语音设置与试听</h2><p>优先选择本地日语声音，在线声音可能受网络影响。这里只调整本站发音，不修改电脑设置。</p><label for="audioVoice">日语声音 · 检测到 ${voices.length} 个</label><select id="audioVoice" ${voices.length?'':'disabled'}>${voices.length?voices.map(v=>`<option value="${esc(v.voiceURI)}" ${voice?.voiceURI===v.voiceURI?'selected':''}>${esc(v.name)} · ${v.localService?'本地':'在线'}</option>`).join(''):'<option>暂无日语声音</option>'}</select><label for="audioSecondVoice">对话角色 B 声音（角色 A 使用上方声音）</label><select id="audioSecondVoice" ${voices.length?'':'disabled'}>${voices.length?voices.map(v=>`<option value="${esc(v.voiceURI)}" ${secondJapaneseVoice()?.voiceURI===v.voiceURI?'selected':''}>${esc(v.name)} · ${v.localService?'本地':'在线'}</option>`).join(''):'<option>暂无日语声音</option>'}</select><p class="completion-note">对话只朗读台词，不读角色标签。有两个日语声音时分别分配给两个角色；只有一个或选择同一声音时，使用不同音高区分。</p><div class="toolbar"><button class="secondary" id="audioDialogueTest" ${voices.length?'':'disabled'}>▷ 试听双角色对话</button><button class="primary" id="audioTest" ${voices.length?'':'disabled'}>▷ 试听：こんにちは</button><button class="secondary" id="audioStop">停止</button><button class="secondary" id="audioRefresh">重新检测声音</button></div><p id="audioStatus" role="status">${esc(audioStatus)}</p><small id="audioError">${audioError?`诊断代码：${esc(audioError)}`:''}</small><div class="hint">${voices.length?'试听成功后，再回到课程播放。重复点击同一句不会重启；不同句子会切换播放，停止与切换不再显示错误。':'浏览器可能尚未加载声音，先点击重新检测。若仍没有，请用 Edge / Chrome 打开本站，或在 Windows 语言设置中添加日语语音后重启浏览器。'}<br>本站课程使用合成语音；官方真题录音仍在「真题训练」独立打开。</div>`;}
const audioDialog=document.createElement('dialog');audioDialog.id='audioDialog';audioDialog.innerHTML='<button id="audioClose" class="close" aria-label="关闭语音设置">×</button><div id="audioBody"></div>';document.body.append(audioDialog);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='audioSettings'){renderAudioSettings();audioDialog.showModal();}if(b.id==='audioClose'){stopAudio();audioDialog.close();}if(b.id==='audioRefresh')renderAudioSettings();if(b.id==='audioTest')speak('こんにちは。日本語を一緒に勉強しましょう。',.85);if(b.id==='audioDialogueTest')speak('李：こんにちは。\n田中：こんにちは。よろしくお願いします。',.85);if(b.id==='audioStop')stopAudio();});
document.addEventListener('change',e=>{if(!['audioVoice','audioSecondVoice'].includes(e.target.id))return;stopAudio();if(e.target.id==='audioVoice')audioVoiceURI=e.target.value;else audioSecondVoiceURI=e.target.value;try{localStorage.setItem('hajime-audio-v1',JSON.stringify({voiceURI:audioVoiceURI,secondVoiceURI:audioSecondVoiceURI}));}catch{}audioState('声音已选择，请点击试听');});
audioDialog.addEventListener('cancel',stopAudio);
audioEngine?.addEventListener?.('voiceschanged',()=>{if(audioDialog.open)renderAudioSettings();});
window.addEventListener('pagehide',stopAudio);
